// Generates machine-readable feeds from the blog content:
//   public/rss.xml  — RSS 2.0 feed for readers and aggregators
//   public/llms.txt — plain-text site overview for AI crawlers/answer engines
//
// Companion to generate-sitemap.mjs; regenerated by the pre-commit hook
// whenever blog content changes.
//
// Run with:  npm run rss

import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";

const ROOT = process.cwd();
const BLOGS_DIR = path.join(ROOT, "content/blogs");
const RSS_OUT = path.join(ROOT, "public/rss.xml");
const LLMS_OUT = path.join(ROOT, "public/llms.txt");

// Same origin default as lib/site.ts.
const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? "https://sk-santhosh.info";

const AUTHOR = "Santhosh Kumar J";
const TITLE = `${AUTHOR} — Blog`;
const DESCRIPTION =
  "Thoughts on DevOps, platform engineering, Kubernetes, cloud infrastructure and SRE.";

const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

const posts = fs
  .readdirSync(BLOGS_DIR)
  .filter((f) => f.endsWith(".md"))
  .map((file) => {
    const { data } = matter(fs.readFileSync(path.join(BLOGS_DIR, file), "utf8"));
    return {
      slug: file.replace(/\.md$/, ""),
      title: data.title,
      description: data.description,
      date: new Date(data.date),
      tags: data.tags ?? [],
    };
  })
  .sort((a, b) => b.date.getTime() - a.date.getTime());

// --- RSS 2.0 ------------------------------------------------------------
const items = posts
  .map(
    (p) => `    <item>
      <title>${esc(p.title)}</title>
      <link>${siteUrl}/blogs/${p.slug}</link>
      <guid isPermaLink="true">${siteUrl}/blogs/${p.slug}</guid>
      <pubDate>${p.date.toUTCString()}</pubDate>
      <description>${esc(p.description)}</description>
${p.tags.map((t) => `      <category>${esc(t)}</category>`).join("\n")}
    </item>`
  )
  .join("\n");

const rss = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${esc(TITLE)}</title>
    <link>${siteUrl}/blogs</link>
    <description>${esc(DESCRIPTION)}</description>
    <language>en</language>
    <lastBuildDate>${posts[0]?.date.toUTCString() ?? new Date().toUTCString()}</lastBuildDate>
    <atom:link href="${siteUrl}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>
`;

fs.writeFileSync(RSS_OUT, rss);
console.log(`✓ public/rss.xml (${posts.length} items)`);

// --- llms.txt -----------------------------------------------------------
// https://llmstxt.org — a concise, markdown-formatted site guide for LLMs.
const llms = `# ${AUTHOR}

> Personal site and blog of ${AUTHOR}, a Platform Engineer, Cloud Engineer and SRE based in Chennai, India, with 14+ years of experience building cloud-native platforms on AWS, Azure and GCP. ${DESCRIPTION}

## Pages

- [Home](${siteUrl}/): Profile, headline delivery metrics, skills and latest writing
- [About](${siteUrl}/about): Experience, core competencies, certifications and education
- [Blogs](${siteUrl}/blogs): All articles
- [Contact](${siteUrl}/contact): How to get in touch

## Blog posts

${posts.map((p) => `- [${p.title}](${siteUrl}/blogs/${p.slug}): ${p.description}`).join("\n")}
`;

fs.writeFileSync(LLMS_OUT, llms);
console.log(`✓ public/llms.txt (${posts.length} posts)`);
